             slices.Add(new(support, owned));
         }
+        GD.Print($"PROFILE_COMPILE {identity} totalMs={profileCompile.Elapsed.TotalMilliseconds:R} membersMs={profileMembersMs:R} alphaMs={profileAlphaTicks * 1000.0 / System.Diagnostics.Stopwatch.Frequency:R} supports={supports.Count} members={document.Members.Length}");
